insert into public.benchmark_assumptions (key, value, unit, label, source_name, source_url, note, provisional, effective_from)
values ('indirect_multiplier_low', 2, 'factor', '{"de":"Gesamtkostenfaktor, tief","en":"Total cost multiplier, low"}'::jsonb, 'ILO (2007), Kostenmodell des Unfall-Eisbergs', 'https://www.ilo.org/media/42526/download', '{"de":"Die ILO hält fest, dass die indirekten Kosten die direkten mindestens erreichen: Gesamtkosten gleich dem Doppelten der versicherten Kosten.","en":"The ILO states that indirect costs at least equal the direct ones: total cost twice the insured cost."}'::jsonb, true, '2007-01-01')
