insert into public.benchmark_assumptions (key, value, unit, label, source_name, source_url, note, provisional, effective_from)
values ('indirect_multiplier', 3.7, 'factor', '{"de":"Gesamtkostenfaktor, mittel","en":"Total cost multiplier, middle"}'::jsonb, 'National Safety Council, Verhältnis 2,7, zitiert im OSHAcademy Kurs 700', 'https://www.oshacademy.com/courses/training/700-introduction-safety-management/700-1-12.php', '{"de":"Indirekte Kosten 2,7 mal die direkten: Gesamtkosten 3,7 mal die versicherten Kosten. Eine US-Zahl, durch eine schweizerische oder europäische Schätzung zu ersetzen.","en":"Indirect costs 2.7 times the direct ones: total 3.7 times the insured cost. A US figure, to be replaced by a Swiss or European estimate."}'::jsonb, true, '2026-09-06')
