values ('indirect_multiplier_high', 5, 'factor', '{"de":"Gesamtkostenfaktor, hoch","en":"Total cost multiplier, high"}'::jsonb, 'Heinrich (1931), Verhältnis 1:4, zitiert im OSHAcademy Kurs 700', 'https://www.oshacademy.com/courses/training/700-introduction-safety-management/700-1-12.php', '{"de":"Indirekte Kosten vier mal die direkten: Gesamtkosten fünf mal die versicherten Kosten.","en":"Indirect costs four times the direct ones: total five times the insured cost."}'::jsonb, true, '1931-01-01')
